const lead = $input.item.json;
const count = parseInt(lead.follow_up_count) || 0;

// ── Safely extract first name ─────────────────────────
let firstName = 'there';
if (lead.first_name && lead.first_name !== '') {
  firstName = lead.first_name;
} else if (lead.full_name && lead.full_name !== '') {
  firstName = lead.full_name.split(' ')[0];
}

// ── Generate token ────────────────────────────────────
const secretKey = 'LeadMgmt2026@Secure';

function generateToken(email, secret) {
  const combined = email + secret + email.length;
  let hash = 0;
  for (let i = 0; i < combined.length; i++) {
    const char = combined.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  const positiveHash = Math.abs(hash).toString(16);
  const extra = (email.length * secret.length).toString(16);
  return (positiveHash + extra + positiveHash)
    .padEnd(32, '0')
    .substring(0, 32);
}

const token = generateToken(lead.email, secretKey);

// ── Build unsubscribe URL ─────────────────────────────
const baseUrl = 'https://bursting-freely-cobra.ngrok-free.app';
const unsubscribeUrl = `${baseUrl}/webhook/unsubscribe?email=${encodeURIComponent(lead.email)}&token=${token}`;

// ── Button links ──────────────────────────────────────
const calLink    = 'https://cal.com/chweet-girl-bsfmon/';
const replyEmail = 'sudhaleela222@gmail.com';

// ── Professional footer with buttons ─────────────────
const unsubscribeFooter = `
<div style="margin-top:48px;padding-top:24px;
border-top:1px solid #eeeeee;text-align:center;
font-family:Arial,sans-serif">

  <p style="font-size:13px;color:#666666;margin:0 0 20px">
    Interested in connecting? We would love to hear from you.
  </p>

  <!-- Book a Call button -->
  <a href="${calLink}"
     style="display:inline-block;
            background-color:#0066FF;
            color:#ffffff;
            font-size:14px;
            font-weight:600;
            text-decoration:none;
            padding:12px 28px;
            border-radius:6px;
            margin:0 8px 12px">
    📅 Book a Call
  </a>

  <!-- Reply to Us button -->
  <a href="mailto:${replyEmail}"
     style="display:inline-block;
            background-color:#ffffff;
            color:#0066FF;
            font-size:14px;
            font-weight:600;
            text-decoration:none;
            padding:12px 28px;
            border-radius:6px;
            border:2px solid #0066FF;
            margin:0 8px 12px">
    ✉️ Reply to Us
  </a>

  <!-- Unsubscribe button -->
  <a href="${unsubscribeUrl}"
